const icons={"/static/app-icon-v2-32.png":"","/static/app-icon-v2-180.png":"","/static/app-icon-v2-192.png":"","/static/app-icon-v2-512.png":""};
export function appIcon(path){const data=icons[path];return data?new Response(Uint8Array.from(atob(data),c=>c.charCodeAt(0)),{headers:{"content-type":"image/png","cache-control":"public, max-age=31536000, immutable","x-content-type-options":"nosniff"}}):null;}

